const e="https://ccs.cpu.edu.ph/wp-content/uploads/2021/",t=[{id:"moa-signing-2021",date:"2021-12-08",topic:"Community",title:"Community Engagement MOA Signing Ceremony",img:e+"12/12072021-Outreach-MOA-1370x550.jpg",url:"https://ccs.cpu.edu.ph/2021/12/08/community-engagement-moa-signing-ceremony/",excerpt:"CPU College of Computer Studies and Mandurriao Elementary School sign a Memorandum of Agreement.",body:["A Memorandum of Agreement between Central Philippine University (CPU) College of Computer Studies (CCS) and Mandurriao Elementary School (MES) was signed on December 7, 2021. The ceremony marks the start of a partnership between the two institutions.","The college’s community engagement program “Adopt a School” was scheduled to hold its first session on December 9, 2021. The program is virtual: CCS faculty members are the instructors and MES faculty members are the participants. The first session covers types of Learning Management Systems (LMS) such as Free Canvas, Google Classroom and Facebook Groups."]},{id:"new-librarians-2021",date:"2021-11-23",topic:"Achievement",title:"Congratulations to our New Librarians!",img:e+"11/11232021-New-Librarians-843x550.jpg",url:"https://ccs.cpu.edu.ph/2021/11/23/congratulations-to-our-new-librarians/",excerpt:"CPU posts a 60% passing rate among first-time takers in the September 2021 Librarians Licensure Examination.",body:["Results of the Librarians Licensure Board Examination of September 2021: CPU recorded a 60% passing percentage for first-time takers, against a 47.7% national passing percentage. Counting first-time takers and retakers together, the passing percentage was 50%.","The CCS family congratulated the new librarians: “To God be the glory!”"]},{id:"kation-hires-2021",date:"2021-11-23",topic:"Industry",title:"Kation Technologies hires CCS graduates",img:e+"11/11232021-Kation-1080x550.jpg",url:"https://ccs.cpu.edu.ph/2021/11/23/kation-technologies-hires-ccs-graduates/",excerpt:"Kation Technologies Inc., a Microsoft Gold Partner company, hires graduates of the college.",body:["Kation Technologies Inc., a Microsoft Gold Partner company in the Philippines enabling people with world-class technology, hired graduates of the College of Computer Studies."]}],a=[{id:"e1",date:"2021-12-07",title:"CCS–Mandurriao Elementary School MOA signing",note:"Start of the partnership between CPU CCS and MES.",newsId:"moa-signing-2021"},{id:"e2",date:"2021-12-09",title:"“Adopt a School” first session (virtual)",note:"CCS faculty teach MES faculty about Learning Management Systems.",newsId:"moa-signing-2021"},{id:"e3",date:"2019-09-16",title:"PAASCU re-survey visit (Sept 16–18, 2019)",note:"Led to a 5-year Level 1 re-accredited status for BSCS, BSIT and BSIS.",newsId:null}];export{a as e,t as n};
